96	        this.telephone = telephone;
97	    }
98	
99	    public String getEmail() {
100	        return this.email;
101	    }
102	
103	    public void setEmail(String email) {
104	        this.email = email;
105	    }
106	
107	    public LocalDate getRegistrationDate() {
108	        return this.registrationDate;
109	    }
110	
111	    public void setRegistrationDate(LocalDate registrationDate) {
112	        this.registrationDate = registrationDate;
113	    }
114	
115	    public String getCustomerCode() {
116	        return this.customerCode;
117	    }
118	
119	    public void setCustomerCode(String customerCode) {
120	        this.customerCode = customerCode;
121	    }
122	
123	    public String getHouseholdId() {
124	        return this.householdId;
125	    }
126	
127	    public void setHouseholdId(String householdId) {
128	        this.householdId = householdId;
129	    }
130	
131	    public Integer getNamesakeCount() {
132	        return this.namesakeCount;
133	    }
134	
135	    public void setNamesakeCount(Integer namesakeCount) {
136	        this.namesakeCount = namesakeCount;
137	    }
138	
139	    /**
140	     * Whether more than 80 owners had already been created today at the time this owner
141	     * was created, indicating an unusually high signup volume.
142	     *
143	     * @return {@code true} when the bulk-signup threshold was exceeded, otherwise
144	     *         {@code false} (never {@code null})
145	     */
146	    public Boolean getBulkSignupWarning() {
147	        return this.bulkSignupWarning != null && this.bulkSignupWarning;
148	    }
149	
150	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
151	        this.bulkSignupWarning = bulkSignupWarning;
152	    }
153	
154	    /**
155	     * The number of owners in this owner's household (owners sharing the same
156	     * {@code householdId}) as of when this owner was created, used to derive the GOLD
157	     * membership tier.
158	     *
159	     * @return the household member count, or {@code null} if it has not been assigned
160	     */
161	    public Integer getHouseholdSize() {
162	        return this.householdSize;
163	    }
164	
165	    public void setHouseholdSize(Integer householdSize) {
166	        this.householdSize = householdSize;
167	    }
168	
169	    /**
170	     * The owner's name formatted as {@code "LastName, FirstName"} from the stored names.
171	     *
172	     * @return the formatted display name
173	     */
174	    public String getDisplayName() {
175	        return this.getLastName() + ", " + this.getFirstName();
176	    }
177	
178	    /**
179	     * The owner's initials: the upper-cased first letters of the first and last
180	     * names, dot-separated with a trailing dot (e.g. {@code "J.S."}).
181	     *
182	     * @return the formatted initials
183	     */
184	    public String getInitials() {
185	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
186	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
187	    }
188	
189	    /**
190	     * The owner's membership number formatted as {@code "<customerCode>-M<YY>"}, where
191	     * {@code YY} is the last two digits of the registration date's year (e.g.
192	     * {@code "SYD-SMI-0007-M26"}).
193	     *
194	     * @return the formatted membership number, or {@code null} if the customer code or
195	     *         registration date has not been assigned
196	     */
197	    public String getMembershipNumber() {
198	        if (this.customerCode == null || this.registrationDate == null) {
199	            return null;
200	        }
201	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
202	    }
203	
204	    /**
205	     * The owner's numeric membership level, from {@code 1} to {@code 3}, computed on
206	     * creation. It starts at {@code 1}, gains {@code 1} when this owner carries an email
207	     * address, gains {@code 1} when this owner has no namesakes ({@code namesakeCount} is
208	     * {@code 0}), and is capped at {@code 3} (level {@code 4} is reserved for tenure).
209	     *
210	     * @return the membership level
211	     */
212	    public Integer getMembershipLevel() {
213	        int level = 1;
214	        boolean hasEmail = this.email != null && !this.email.isBlank();
215	        if (hasEmail) {
216	            level++;
217	        }
218	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
219	        if (noNamesakes) {
220	            level++;
221	        }
222	        return Math.min(level, 3);
223	    }
224	
225	    /**
226	     * The owner's preferred contact channel: {@code "EMAIL"} when the owner carries an
227	     * email address, otherwise {@code "PHONE"}.
228	     *
229	     * @return {@code "EMAIL"} when an email is present, otherwise {@code "PHONE"}
230	     */
231	    public String getContactPreference() {
232	        boolean hasEmail = this.email != null && !this.email.isBlank();
233	        return hasEmail ? "EMAIL" : "PHONE";
234	    }
235	
236	    /**
237	     * The owner's identity key: the single derived value used for duplicate detection, formed as
238	     * {@code normalizedTelephone + "|" + (email or empty) + "|" + householdId}. The telephone and
239	     * email are the already-normalized stored values and a {@code null} email or household id is
240	     * rendered as the empty string. Two owners are duplicates only when their whole identity keys
241	     * are equal; because the telephone is part of the key, household members with different
242	     * telephones have different identity keys.
243	     *
244	     * @return the derived identity key
245	     */
246	    public String getIdentityKey() {
247	        String telephonePart = this.telephone == null ? "" : this.telephone;
248	        String emailPart = this.email == null ? "" : this.email;
249	        String householdPart = this.householdId == null ? "" : this.householdId;
250	        return telephonePart + "|" + emailPart + "|" + householdPart;
251	    }
252	
253	    /**
254	     * City -> canonical region, the fixed ground truth for deriving locality.
255	     */
256	    private static final Map<String, String> CITY_REGION = Map.of(
257	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
258	
259	    /**
260	     * The owner's locality: the canonical region derived from the city using the fixed
261	     * city-to-region table ({@code Sydney->NSW}, {@code Melbourne->VIC},
262	     * {@code Brisbane->QLD}), or {@code "UNKNOWN"} when the city is not in the table.
263	     *
264	     * @return the canonical region string, or {@code "UNKNOWN"}
265	     */
266	    public String getLocality() {
267	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
268	    }
269	
270	    protected Set<Pet> getPetsInternal() {
271	        if (this.pets == null) {
272	            this.pets = new HashSet<>();
273	        }
274	        return this.pets;
275	    }
276	
277	    protected void setPetsInternal(Set<Pet> pets) {
278	        this.pets = pets;
279	    }
280	
281	    public List<Pet> getPets() {
282	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
283	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
284	        return Collections.unmodifiableList(sortedPets);
285	    }
286	
287	    public void setPets(List<Pet> pets) {
288	        this.pets = new HashSet<>(pets);
289	    }
290	
291	    public void addPet(Pet pet) {
292	        getPetsInternal().add(pet);
293	        pet.setOwner(this);
294	    }
295	
296	    /**
