49	import org.springframework.samples.petclinic.service.ClinicService;
50	import org.springframework.security.access.prepost.PreAuthorize;
51	import org.springframework.web.bind.annotation.CrossOrigin;
52	import org.springframework.web.bind.annotation.RequestMapping;
53	import org.springframework.web.bind.annotation.RestController;
54	import org.springframework.web.util.UriComponentsBuilder;
55	
56	import jakarta.transaction.Transactional;
57	
58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    /**
68	     * Pattern for a syntactically valid email address: a non-empty local part, an '@', and a
69	     * dotted domain ending in a letters-only label. Applied to the trimmed, lower-cased value.
70	     */
71	    /**
72	     * Dedicated audit logger. Successful side-effects (e.g. owner creation) are recorded here so
73	     * they can be routed and asserted independently of the application's diagnostic logging.
74	     */
75	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
76	
77	    private static final Pattern EMAIL_PATTERN =
78	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
79	
80	    /**
81	     * Common address abbreviations expanded to their full form during address normalization.
82	     * Matching is performed per whitespace-separated token on the upper-cased value.
83	     */
84	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
85	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
86	
87	    /**
88	     * Required national-number length (the digits after the country code) per E.164 country code.
89	     * A number whose country code appears here must carry exactly the mapped number of national
90	     * digits; country codes not listed fall back to the generic 8-to-15 total-digit rule.
91	     */
92	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
93	        Map.of("61", 9, "1", 10);
94	
95	    private final ClinicService clinicService;
96	
97	    private final OwnerMapper ownerMapper;
98	
99	    private final PetMapper petMapper;
100	
101	    private final VisitMapper visitMapper;
102	
103	    public OwnerRestControllerV1(ClinicService clinicService,
104	                                 OwnerMapper ownerMapper,
105	                                 PetMapper petMapper,
106	                                 VisitMapper visitMapper) {
107	        this.clinicService = clinicService;
108	        this.ownerMapper = ownerMapper;
109	        this.petMapper = petMapper;
110	        this.visitMapper = visitMapper;
111	    }
112	
113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
116	        Collection<Owner> owners;
117	        if (lastName != null) {
118	            owners = this.clinicService.findOwnerByLastName(lastName);
119	        } else {
120	            owners = this.clinicService.findAllOwners();
121	        }
122	        if (owners.isEmpty()) {
123	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
124	        }
125	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
126	    }
127	
128	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
129	    @Override
130	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
131	        Owner owner = this.clinicService.findOwnerById(ownerId);
132	        if (owner == null) {
133	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
134	        }
135	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
136	    }
137	
138	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
139	    @Override
140	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
141	        HttpHeaders headers = new HttpHeaders();
142	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
143	        LocalDate effectiveDate = owner.getRegistrationDate() != null
144	            ? owner.getRegistrationDate() : LocalDate.now();
145	        LocalDate registrationDate = toBusinessDay(effectiveDate);
146	        owner.setRegistrationDate(registrationDate);
147	        long createdToday = this.clinicService.findAllOwners().stream()
148	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
149	            .count();
150	        if (createdToday >= 100) {
151	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
152	        }
153	        owner.setBulkSignupWarning(createdToday > 80);
154	        String address = normalizeAddress(owner.getAddress());
155	        if (address == null || address.isEmpty()) {
156	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
157	        }
158	        owner.setAddress(address);
159	        String telephone = toE164(owner.getTelephone());
160	        if (telephone == null) {
161	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
162	        }
163	        owner.setTelephone(telephone);
164	        if (owner.getEmail() != null) {
165	            String email = normalizeEmail(owner.getEmail());
166	            if (!EMAIL_PATTERN.matcher(email).matches()) {
167	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
168	            }
169	            owner.setEmail(email);
170	        }
171	        String cityKey = householdKey(owner.getCity());
172	        long cityCount = this.clinicService.findAllOwners().stream()
173	            .filter(existing -> existing.getCity() != null
174	                && cityKey.equals(householdKey(existing.getCity())))
175	            .count();
176	        if (cityCount >= 50) {
177	            return new ResponseEntity<>(HttpStatus.CONFLICT);
178	        }
179	        String lastNameKey = householdKey(owner.getLastName());
180	        String addressKey = householdKey(owner.getAddress());
181	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
182	            .filter(existing -> lastNameKey.equals(householdKey(existing.getLastName()))
183	                && addressKey.equals(householdKey(existing.getAddress())))
184	            .toList();
185	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
186	        if (sharesHousehold) {
187	            String householdId = householdMembers.stream()
188	                .map(Owner::getHouseholdId)
189	                .filter(Objects::nonNull)
190	                .findFirst()
191	                .orElseGet(() -> householdId(owner));
192	            owner.setHouseholdId(householdId);
193	            owner.setHouseholdSize(householdMembers.size() + 1);
194	        } else {
195	            owner.setHouseholdSize(1);
196	        }
197	        // Single consolidated duplicate check: the telephone, email and household duplicate rules are
198	        // all expressed through the one derived identityKey (telephone|email|householdId). A create is
199	        // rejected only when a new owner's WHOLE identityKey equals an existing owner's; because the
200	        // telephone is part of the key, two household members with different telephones are allowed.
201	        String identityKey = owner.getIdentityKey();
202	        boolean identityInUse = this.clinicService.findAllOwners().stream()
203	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
204	        if (identityInUse) {
205	            return new ResponseEntity<>(HttpStatus.CONFLICT);
206	        }
207	        if (sharesHousehold) {
208	            for (Owner member : householdMembers) {
209	                if (member.getHouseholdId() == null) {
210	                    member.setHouseholdId(owner.getHouseholdId());
211	                    this.clinicService.saveOwner(member);
212	                }
213	            }
214	        }
215	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
216	        String firstNameKey = householdKey(owner.getFirstName());
217	        String namesakeLastNameKey = householdKey(owner.getLastName());
218	        long namesakeCount = this.clinicService.findAllOwners().stream()
219	            .filter(existing -> firstNameKey.equals(householdKey(existing.getFirstName()))
220	                && namesakeLastNameKey.equals(householdKey(existing.getLastName())))
221	            .count();
222	        owner.setNamesakeCount((int) namesakeCount);
223	        this.clinicService.saveOwner(owner);
224	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
225	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
226	            owner.getMembershipLevel());
227	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
228	        headers.setLocation(UriComponentsBuilder.newInstance()
229	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
230	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
231	    }
232	
233	    /**
234	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped.
235	     * When the value carries a leading {@code '+'} its country code is kept as given; otherwise the
236	     * Australian country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped
237	     * from the national digits. The result must carry 8 to 15 digits after the {@code '+'}. For
238	     * recognised country codes the national number (the digits after the country code) must also be
239	     * exactly the length that country requires ({@code '+61'} needs 9 national digits, {@code '+1'}
240	     * needs 10); a wrong national-number length yields {@code null}.
241	     *
242	     * @param telephone the raw telephone value (may be {@code null})
243	     * @return the E.164 telephone (e.g. {@code "+61412345678"}), or {@code null} if it cannot form
244	     *         a valid E.164 number
245	     */
246	    private String toE164(String telephone) {
247	        if (telephone == null) {
248	            return null;
249	        }
250	        String trimmed = telephone.trim();
251	        boolean hasCountryCode = trimmed.startsWith("+");
252	        String cleaned = trimmed.replaceAll("[\\s()\\[\\]-]", "");
253	        if (hasCountryCode) {
254	            cleaned = cleaned.substring(1);
255	        }
256	        if (!cleaned.matches("[0-9]+")) {
257	            return null;
258	        }
259	        String digits;
260	        if (hasCountryCode) {
261	            digits = cleaned;
262	        } else {
263	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
264	            digits = "61" + national;
265	        }
266	        if (digits.length() < 8 || digits.length() > 15) {
267	            return null;
268	        }
269	        if (!hasValidNationalNumberLength(digits)) {
270	            return null;
271	        }
272	        return "+" + digits;
273	    }
274	
275	    /**
276	     * Checks the national-number length of an E.164 digit string (country code plus national
277	     * number, without the leading {@code '+'}) against its country code. When the number's country
278	     * code is one of the {@link #NATIONAL_NUMBER_LENGTHS recognised codes}, the digits after the
279	     * country code must number exactly what that country requires; the longest matching country
280	     * code wins. Numbers whose country code is not recognised are accepted here (they are governed
281	     * only by the generic total-length rule).
282	     *
283	     * @param digits the E.164 digits without the leading {@code '+'} (e.g. {@code "61412345678"})
284	     * @return {@code true} if the national-number length is acceptable for the country code
285	     */
286	    private boolean hasValidNationalNumberLength(String digits) {
287	        return NATIONAL_NUMBER_LENGTHS.entrySet().stream()
288	            .filter(entry -> digits.startsWith(entry.getKey()))
289	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
290	            .map(entry -> digits.length() - entry.getKey().length() == entry.getValue())
291	            .orElse(true);
292	    }
293	
294	    /**
295	     * Normalizes an email address for storage by trimming surrounding whitespace and lower-casing
296	     * it. The result is validated by the caller against {@link #EMAIL_PATTERN}.
297	     *
298	     * @param email the raw email value (must not be {@code null})
299	     * @return the trimmed, lower-cased email
300	     */
301	    private String normalizeEmail(String email) {
302	        return email.trim().toLowerCase(Locale.ROOT);
303	    }
304	
305	    /**
306	     * Normalizes a postal address for storage and comparison: surrounding whitespace is trimmed,
307	     * internal runs of whitespace are collapsed to a single space, the value is upper-cased and
308	     * common street-type abbreviations are expanded per token ({@code ST -> STREET},
309	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). The stored and returned address is this
310	     * normalized form, and every household comparison uses it.
311	     *
312	     * @param address the raw address value (may be {@code null})
313	     * @return the normalized address, or {@code null} if the input was {@code null}
314	     */
315	    private String normalizeAddress(String address) {
316	        if (address == null) {
317	            return null;
318	        }
319	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
320	        if (collapsed.isEmpty()) {
321	            return collapsed;
322	        }
323	        String[] tokens = collapsed.split(" ");
324	        StringBuilder sb = new StringBuilder(collapsed.length());
325	        for (int i = 0; i < tokens.length; i++) {
326	            if (i > 0) {
327	                sb.append(' ');
328	            }
329	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
330	        }
331	        return sb.toString();
332	    }
333	
334	    /**
335	     * Normalizes a value for household-duplicate comparison: surrounding whitespace is trimmed,
336	     * internal runs of whitespace are collapsed to a single space and the result is lower-cased,
337	     * so that owners are compared case-insensitively with collapsed whitespace.
338	     *
339	     * @param value the raw value (must not be {@code null})
340	     * @return the normalized comparison key
341	     */
342	    private String householdKey(String value) {
343	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
344	    }
345	
346	    /**
347	     * Derives a stable, shared household identifier for the owner's household. The value is a
348	     * deterministic function of the normalized last name and address ({@link #householdKey}), so
349	     * every owner in the same household derives the identical identifier of the form
350	     * {@code 'HH-<12 upper-case hex>'}.
351	     *
352	     * @param owner the owner whose household identifier is derived
353	     * @return the stable household identifier
354	     */
355	    private String householdId(Owner owner) {
356	        String key = householdKey(owner.getLastName()) + "|" + householdKey(owner.getAddress());
357	        try {
358	            byte[] digest = MessageDigest.getInstance("SHA-256")
359	                .digest(key.getBytes(StandardCharsets.UTF_8));
360	            StringBuilder sb = new StringBuilder(digest.length * 2);
361	            for (byte b : digest) {
362	                sb.append(String.format("%02x", b));
363	            }
364	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
365	        }
366	        catch (java.security.NoSuchAlgorithmException e) {
367	            throw new IllegalStateException("SHA-256 not available", e);
368	        }
369	    }
370	
371	    /**
372	     * Builds the customer code for a newly registered owner in the form
373	     * {@code '<CITY3>-<LAST3>-<NNNN>'}, where {@code CITY3} is the upper-cased first three
374	     * letters of the city, {@code LAST3} the upper-cased first three letters of the last name
375	     * and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more than the
376	     * number of owners already registered in that city (e.g. {@code 'SYD-SMI-0007'}).
377	     *
378	     * @param city     the owner's city
379	     * @param lastName the owner's last name
380	     * @return the assigned customer code
381	     */
382	    private String nextCustomerCode(String city, String lastName) {
383	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
384	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
385	        String cityKey = householdKey(city);
386	        int sequence = (int) this.clinicService.findAllOwners().stream()
387	            .filter(existing -> existing.getCity() != null && cityKey.equals(householdKey(existing.getCity())))
388	            .count() + 1;
389	        return String.format(Locale.ROOT, "%s-%s-%04d", city3, last3, sequence);
390	    }
391	
392	    /**
393	     * Rolls a registration date forward onto a business day. When the given date falls on a
394	     * Saturday or Sunday it is advanced to the following Monday; a weekday is returned unchanged.
395	     *
396	     * @param date the effective registration date (must not be {@code null})
397	     * @return the same date if it is a weekday, otherwise the next Monday
398	     */
399	    private LocalDate toBusinessDay(LocalDate date) {
400	        DayOfWeek dayOfWeek = date.getDayOfWeek();
401	        if (dayOfWeek == DayOfWeek.SATURDAY) {
402	            return date.plusDays(2);
403	        }
404	        if (dayOfWeek == DayOfWeek.SUNDAY) {
405	            return date.plusDays(1);
406	        }
407	        return date;
408	    }
409	
410	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
411	    @Override
412	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
413	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
414	        if (currentOwner == null) {
415	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
416	        }
417	        String email = ownerFieldsDto.getEmail();
418	        if (email != null) {
419	            email = normalizeEmail(email);
420	            if (!EMAIL_PATTERN.matcher(email).matches()) {
421	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
422	            }
423	        }
424	        String telephone = toE164(ownerFieldsDto.getTelephone());
425	        if (telephone == null) {
426	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
427	        }
428	        currentOwner.setAddress(ownerFieldsDto.getAddress());
429	        currentOwner.setCity(ownerFieldsDto.getCity());
430	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
431	        currentOwner.setLastName(ownerFieldsDto.getLastName());
432	        currentOwner.setTelephone(telephone);
433	        currentOwner.setEmail(email);
434	        this.clinicService.saveOwner(currentOwner);
435	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
436	    }
437	
438	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
439	    @Transactional
440	    @Override
441	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
442	        Owner owner = this.clinicService.findOwnerById(ownerId);
443	        if (owner == null) {
444	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
445	        }
446	        this.clinicService.deleteOwner(owner);
447	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
448	    }
449	
450	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
451	    @Override
452	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
453	        Owner owner = this.clinicService.findOwnerById(ownerId);
454	        if (owner == null) {
455	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
456	        }
457	        HttpHeaders headers = new HttpHeaders();
458	        Pet pet = petMapper.toPet(petFieldsDto);
459	        owner.setId(ownerId);
460	        pet.setOwner(owner);
461	        pet.getType().setName(null);
462	        this.clinicService.savePet(pet);
463	        PetDto petDto = petMapper.toPetDto(pet);
464	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
465	            .buildAndExpand(pet.getId()).toUri());
466	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
467	    }
468	
469	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
470	    @Override
471	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
472	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
473	        if (currentOwner != null) {
